import { CircleAlert, TrashIcon } from "lucide-react";
import { useTranslation } from "react-i18next";
import { Button } from "@/modules/ui/components/button";
import {
  Dialog,
  DialogBody,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/modules/ui/components/dialog";

interface DeleteDialogProps {
  open: boolean;
  setOpen: (open: boolean) => void;
  deleteWhat: string;
  onDelete: () => void;
  text?: string;
  isDeleting?: boolean;
  isSaving?: boolean;
  useSaveInsteadOfCancel?: boolean;
  onSave?: () => void;
  children?: React.ReactNode;
  disabled?: boolean;
  title?: string;
  buttonLabel?: string;
}

export const DeleteDialog = ({
  open,
  setOpen,
  deleteWhat,
  onDelete,
  text,
  isDeleting,
  isSaving,
  useSaveInsteadOfCancel = false,
  onSave,
  children,
  disabled,
  title,
  buttonLabel,
}: DeleteDialogProps) => {
  const { t } = useTranslation();
  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent width="narrow" hideCloseButton={true} disableCloseOnOutsideClick={true}>
        <DialogHeader>
          <div className="flex items-center gap-2">
            <CircleAlert className="size-4" />
            <div>
              <DialogTitle>{title || t("common.delete_what", { deleteWhat })}</DialogTitle>
              <DialogDescription>{t("workspace.general.this_action_cannot_be_undone")}</DialogDescription>
            </div>
          </div>
        </DialogHeader>

        <DialogBody>
          <p>{text}</p>
          {children && <div>{children}</div>}
        </DialogBody>

        <DialogFooter>
          <Button
            loading={isSaving}
            variant="secondary"
            onClick={() => {
              if (useSaveInsteadOfCancel && onSave) {
                onSave();
              }
              setOpen(false);
            }}
            disabled={isDeleting || isSaving}>
            {useSaveInsteadOfCancel ? t("common.save") : t("common.cancel")}
          </Button>
          <Button
            variant="destructive"
            onClick={onDelete}
            loading={isDeleting}
            disabled={disabled || isDeleting || isSaving}>
            <TrashIcon />
            {buttonLabel || t("common.delete")}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

import "server-only";
import { prisma } from "@formbricks/database";
import { PrismaErrorType } from "@formbricks/database/types/error";
import { ZId } from "@formbricks/types/common";
import { Result, err, ok } from "@formbricks/types/error-handlers";
import { TTag } from "@formbricks/types/tags";
import { isPrismaKnownRequestError, isUniqueConstraintError } from "@/lib/utils/prisma-error";
import { validateInputs } from "@/lib/utils/validate";
import { TagError } from "@/modules/workspaces/settings/types/tag";

export const deleteTag = async (
  id: string
): Promise<Result<TTag, { code: TagError; message: string; meta?: Record<string, string> }>> => {
  validateInputs([id, ZId]);

  try {
    const tag = await prisma.tag.delete({
      where: {
        id,
      },
    });

    return ok(tag);
  } catch (error) {
    if (isPrismaKnownRequestError(error, PrismaErrorType.RecordNotFound)) {
      return err({
        code: TagError.TAG_NOT_FOUND,
        message: "Tag not found",
      });
    }

    return err({
      code: TagError.UNEXPECTED_ERROR,
      message: error instanceof Error ? error.message : "Unknown error occurred",
    });
  }
};

export const updateTagName = async (
  id: string,
  name: string
): Promise<Result<TTag, { code: TagError; message: string; meta?: Record<string, string> }>> => {
  try {
    const tag = await prisma.tag.update({
      where: { id },
      data: { name },
    });

    return ok(tag);
  } catch (error) {
    if (isUniqueConstraintError(error)) {
      return err({
        code: TagError.TAG_NAME_ALREADY_EXISTS,
        message: "Tag with this name already exists",
      });
    }

    return err({
      code: TagError.UNEXPECTED_ERROR,
      message: error instanceof Error ? error.message : "Unknown error occurred",
    });
  }
};

export const mergeTags = async (
  originalTagId: string,
  newTagId: string
): Promise<Result<TTag, { code: TagError; message: string; meta?: Record<string, string> }>> => {
  validateInputs([originalTagId, ZId], [newTagId, ZId]);

  if (originalTagId === newTagId) {
    return err({
      code: TagError.MERGE_SAME_TAG,
      message: "Cannot merge a tag into itself",
    });
  }

  try {
    let originalTag: TTag | null;

    originalTag = await prisma.tag.findUnique({
      where: {
        id: originalTagId,
      },
    });

    if (!originalTag) {
      return err({
        code: TagError.TAG_NOT_FOUND,
        message: "Tag not found",
      });
    }

    let newTag: TTag | null;

    newTag = await prisma.tag.findUnique({
      where: {
        id: newTagId,
      },
    });

    if (!newTag) {
      return err({
        code: TagError.TAG_NOT_FOUND,
        message: "Tag not found",
      });
    }

    // Find responses that have both tags to avoid unique constraint violations during merge
    const responsesWithBothTags = await prisma.response.findMany({
      where: {
        AND: [{ tags: { some: { tagId: originalTagId } } }, { tags: { some: { tagId: newTagId } } }],
      },
      select: { id: true },
    });

    const conflictResponseIds = responsesWithBothTags.map((r) => r.id);

    await prisma.$transaction([
      // Remove originalTag from responses that already have newTag (prevents unique constraint violation)
      ...(conflictResponseIds.length > 0
        ? [
            prisma.tagsOnResponses.deleteMany({
              where: {
                responseId: { in: conflictResponseIds },
                tagId: originalTagId,
              },
            }),
          ]
        : []),
      // Move all remaining originalTag associations to newTag
      prisma.tagsOnResponses.updateMany({
        where: { tagId: originalTagId },
        data: { tagId: newTagId },
      }),
      // Delete the original tag
      prisma.tag.delete({ where: { id: originalTagId } }),
    ]);

    return ok(newTag);
  } catch (error) {
    return err({
      code: TagError.UNEXPECTED_ERROR,
      message: error instanceof Error ? error.message : "Unknown error occurred",
    });
  }
};

