"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { deleteUnusedTags } from "../lib/api-client";
import { tagKeys } from "../lib/query";

/** Bulk-delete unused tags, then invalidate the list. */
export const useDeleteUnusedTags = (workspaceId: string) => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (variables: { workspaceId: string }) => deleteUnusedTags(variables),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: tagKeys.list(workspaceId) }),
  });
};

import type { TV3Tag } from "@/app/api/v3/tags/serializers";
import { parseV3ApiError } from "@/modules/api/lib/v3-client";

/**
 * Client fetchers for the tags v3 routes. Reads forward the TanStack `signal`; every call throws a parsed
 * `V3ApiError` on a non-2xx response, so the hooks can surface the server's own message.
 */

const BASE_PATH = "/api/v3/tags";

async function request<T>(url: string, init: RequestInit): Promise<T> {
  const response = await fetch(url, { cache: "no-store", ...init });
  if (!response.ok) {
    throw await parseV3ApiError(response);
  }
  return ((await response.json()) as { data: T }).data;
}

export async function getTags(params: { workspaceId: string; signal?: AbortSignal }): Promise<TV3Tag[]> {
  const query = new URLSearchParams({ workspaceId: params.workspaceId });
  return request<TV3Tag[]>(`${BASE_PATH}?${query.toString()}`, {
    method: "GET",
    signal: params.signal,
  });
}

export async function renameTag(params: { tagId: string; name: string }): Promise<TV3Tag> {
  return request<TV3Tag>(`${BASE_PATH}/${params.tagId}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name: params.name }),
  });
}

export async function deleteTag(params: { tagId: string }): Promise<{ id: string }> {
  return request<{ id: string }>(`${BASE_PATH}/${params.tagId}`, { method: "DELETE" });
}

export async function mergeTags(params: { tagId: string; newTagId: string }): Promise<{ id: string }> {
  return request<{ id: string }>(`${BASE_PATH}/${params.tagId}/merge`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ newTagId: params.newTagId }),
  });
}

export async function deleteUnusedTags(params: { workspaceId: string }): Promise<{ deletedCount: number }> {
  const query = new URLSearchParams({ workspaceId: params.workspaceId });
  return request<{ deletedCount: number }>(`${BASE_PATH}/delete-unused?${query.toString()}`, {
    method: "DELETE",
  });
}

/**
 * DELETE /api/v3/tags/delete-unused — delete all unused tags of the workspace.
 *
 * The workspace is resolved from the authenticated user's access, matching the pattern used by
 * other v3 tag mutations. Session-only.
 */
import { z } from "zod";
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { deleteUnusedV3Tags } from "../lib/operations";

export const DELETE = withV3ApiWrapper({
  auth: "session",
  action: "deleted",
  targetType: "tag",
  schemas: { query: z.object({ workspaceId: z.string().cuid2() }).strict() },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    deleteUnusedV3Tags({
      authentication,
      workspaceId: parsedInput.query.workspaceId,
      auditLog,
      requestId,
      instance,
    }),
});

  if (auditLog) auditLog.newObject = result.data;

  return successResponse({ id: newTagId }, { requestId });
}

export async function deleteUnusedV3Tags(
  params: TBaseParams & { workspaceId: string; auditLog?: TV3AuditLog }
): Promise<Response> {
  const { workspaceId, authentication, requestId, instance } = params;

  const access = await requireV3WorkspaceAccess(authentication, workspaceId, "readWrite", requestId, instance);
  if (access instanceof Response) return access;

  // Find all tags in this workspace that have zero response associations
  const tags = await getTagsByWorkspaceId(workspaceId);

  // Get tags that have zero count (not used on any response)
  const countByTagId = new Map(
    (
      await getTagsOnResponsesCount(
        workspaceId,
        buildVisibleSurveyWhere(await resolveV3ResponsesActorContext(authentication, access.organizationId))
      )
    ).map((entry) => [entry.tagId, entry.count])
  );

  const unusedTagIds = tags
    .filter((tag) => countByTagId.get(tag.id) === 0)
    .map((tag) => tag.id);

  if (unusedTagIds.length === 0) {
    return successResponse({ deletedCount: 0 }, { requestId });
  }

  // Delete the unused tags (Prisma's deleteMany cascades to tagsOnResponses)
  const result = await prisma.tag.deleteMany({
    where: {
      id: { in: unusedTagIds },
      workspaceId,
    },
  });

  if (auditLog) {
    auditLog.organizationId = access.organizationId;
    auditLog.targetId = unusedTagIds.join(",");
    auditLog.oldObject = { tagIds: unusedTagIds, deletedCount: result.count };
  }

  return successResponse({ deletedCount: result.count }, { requestId });
}

